// >>> [5, 15, 25, 37, 79]
// >>> comb_sort([41, 32, 15, 19, 22])
// >>> [15, 19, 22, 32, 41]
// >>> comb_sort([99, 15, 13, 47])
// >>> [13, 15, 47, 99]
func comb_sort (nums []int) []int {
	var (
		gap = len(nums)
		swapped = true
	)
	for gap > 1 || swapped {
		if gap > 1 {
			gap = int(float64(gap) / 1.3)
		}
		swapped = false
		for i := 0; i < len(nums) - gap; i++ {
			if nums[i] > nums[i + gap] {
				nums[i], nums[i + gap] = nums[i + gap], nums[i]
				swapped = true
			}
		}
	}
	return nums
}

