// >>> [7, 11, 19, 25, 33, 45, 78]
// >>> merge_sort([3, 1, 4, 9, 8])
// >>> [1, 3, 4, 8, 9]
func merge_sort (x []int) []int {
	if len(x) < 2 {
		return x
	}
	mid := len(x) / 2
	left := merge_sort(x[:mid])
	right := merge_sort(x[mid:])
	return merge(left, right)
}

func merge(left, right []int) []int {
	result := make([]int, len(left) + len(right))
	i, j := 0, 0
	for k := 0; k < len(result); k++ {
		if i >= len(left) {
			result[k] = right[j]
			j++
		} else if j >= len(right) {
			result[k] = left[i]
			i++
		} else if left[i] < right[j] {
			result[k] = left[i]
			i++
		} else {
			result[k] = right[j]
			j++
		}
	}
	return result
}

