				return false
			}
			top := stack[len(stack)-1]
			if v == ')' && top != '(' {
				return false
			} else if v == ']' && top != '[' {
				return false
			} else if v == '}' && top != '{' {
				return false
			}
			stack = stack[:len(stack)-1]
		}
	}
	if len(stack) == 0 {
		return true
	}
	return false
}

