// Write a function to decode a run-length encoded given list.
// Examples:
// >>> decode_list([[2, 1], 2, 3, [2, 4], 5,1])
// >>> [1,1,2,3,4,4,5,1]
// >>> decode_list(['a', 'u', 't', 'o', 'm', 'a', 't', 'i', 'c', 'a', [2, 'l'], 'y'])
// >>> ['a', 'u', 't', 'o', 'm', 'a', 't', 'i', 'c', 'a', 'l', 'l', 'y']
// >>> decode_list(['p', 'y', 't', 'h', 'o', 'n'])
// >>> ['p', 'y', 't', 'h', 'o', 'n']
func decode_list (alist []interface{}) []interface{} {
	var result []interface{}
	for _, v := range alist {
		switch v.(type) {
		case []interface{}:
			result = append(result, decode_list(v.([]interface{}))...)
		default:
			result = append(result, v)
		}
	}
	return result
}

