func get_Inv_Count (arr []int, n int) int {
	if n == 1 {
		return 0
	}
	mid := n/2
	left := get_Inv_Count(arr[:mid], mid)
	right := get_Inv_Count(arr[mid:], n-mid)
	inv_count := left + right
	i := 0
	j := mid
	k := 0
	for i < mid && j < n {
		if arr[i] <= arr[j] {
			arr[k] = arr[i]
			i++
		} else {
			arr[k] = arr[j]
			inv_count += (mid - i)
			j++
		}
		k++
	}
	for i < mid {
		arr[k] = arr[i]
		i++
		k++
	}
	for j < n {
		arr[k] = arr[j]
		j++
		k++
	}
	return inv_count
}

