// >>> Sort([['rishi', 10], ['akhil', 5], ['ramya', 20], ['gaur', 15]])
// >>> [['akhil', 5], ['rishi', 10], ['gaur', 15], ['ramya', 20]]
func Sort (sub_li [][]interface{}) [][]interface{} {
	var li [][]interface{}
	for _, v := range sub_li {
		li = append(li, v)
	}
	sort.Slice(li, func(i, j int) bool {
		return li[i][1].(int) < li[j][1].(int)
	})
	return li
}

