// Write a function to calculate the number of digits and letters in a string.
// Examples:
// >>> dig_let("python")
// >>> (6,0)
// >>> dig_let("program")
// >>> (7,0)
// >>> dig_let("python3.0")
// >>> (6,2)
func dig_let (s string) []int {
	var digits int
	var letters int
	for _, c := range s {
		if c >= '0' && c <= '9' {
			digits++
		} else if c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' {
			letters++
		}
	}
	return []int{digits, letters}
}

