func shell_sort (my_list []int) []int {
	var temp int
	var i, j, gap int
	for gap = len(my_list)/2; gap > 0; gap = gap/2 {
		for i = gap; i < len(my_list); i++ {
			temp = my_list[i]
			for j = i; j >= gap && my_list[j-gap] > temp; j = j-gap {
				my_list[j] = my_list[j-gap]
			}
			my_list[j] = temp
		}
	}
	return my_list
}

