// >>> text_match_all("abbba")
// >>> ('Found a match!')
// >>> text_match_all("abbbba")
// >>> ('Found a match!')
func text_match_all (text string) string {
	if len(text) < 2 {
		return "Not matched!"
	}
	if text[0] == 'a' && text[1] == 'b' {
		return "Found a match!"
	}
	if len(text) > 2 {
		return text_match_all(text[1:])
	}
	return "Not matched!"
}

